func createSubmitTxBody(arc *ArcClient, tx *broadcast.Transaction, txFormat broadcast.TransactionFormat) ([]byte, error) {
	rawTx := tx.Hex

	if txFormat == broadcast.RawTxFormat {
		convertedRawTx, err := convertToEfTransaction(arc, rawTx)
		if err != nil {
			return nil, fmt.Errorf("Conversion to EF format failed: %s", err.Error())
		}
		rawTx = convertedRawTx
	} else if txFormat == broadcast.BeefFormat {
		// To be implemented
		return nil, fmt.Errorf("Submitting transactions in BEEF format is unimplemented yet...")
	}

	body := &SubmitTxRequest{RawTx: rawTx}
	data, err := json.Marshal(body)
	if err != nil {
		return nil, ErrSubmitTxMarshal
	}

	return data, nil
}

if txFormat == broadcast.RawTxFormat {
	convertedRawTxs, err := convertBatchToEfTransaction(arc, rawTxs)
	if err != nil {
		return nil, fmt.Errorf("Conversion to EF format failed for one or more transactions with error: %s", err.Error())
	}
	rawTxs = convertedRawTxs

func convertToEfTransaction(arc *ArcClient, rawTx string) (string, error) {
	transaction, err := bt.NewTxFromString(rawTx)
	if err != nil {
		return "", err
	}

	for _, input := range transaction.Inputs {
		if err = updateUtxoWithMissingData(arc, input); err != nil {
			return "", err
		}
	}

	return hex.EncodeToString(transaction.ExtendedBytes()), nil
}

func convertBatchToEfTransaction(arc *ArcClient, rawTxs []*SubmitTxRequest) ([]*SubmitTxRequest, error) {
	convertedRawTxs := make([]*SubmitTxRequest, 0, len(rawTxs))
	for _, rawTx := range rawTxs {
		convertedRawTx, err := convertToEfTransaction(arc, rawTx.RawTx)
		if err != nil {
			return nil, err
		}
		convertedRawTxs = append(convertedRawTxs, &SubmitTxRequest{RawTx: convertedRawTx})
	}
	return convertedRawTxs, nil
}

